#include <algorithm>
#include <iostream>
#include <memory>
#include <numbers>      // std::numbers::pi: the constant pi as a double
#include <string>
#include <vector>

class Shape
{
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual double perimeter() const = 0;
    virtual std::string name() const = 0;
};

class Circle : public Shape
{
public:
    explicit Circle(double r) : m_r{ r } {}
    double area() const override { return std::numbers::pi * m_r * m_r; }
    double perimeter() const override { return 2 * std::numbers::pi * m_r; }
    std::string name() const override { return "Circle r=" + std::to_string(m_r); }

private:
    double m_r{};
};

